"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3071],{55146:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"LobbySharedPackets","desc":"The packets both places use: join sync, XP, coins, permanent perks and shop\\nperks. `Packets` re-exports every one of them, so callers always require\\n`SharedModules.Packets`. They live in this child module so the Lobby can map\\nthem WITHOUT the gameplay packets in `Packets/init` (that module creates the\\nplacement ghost `UnreliableRemoteEvent`s on require). The Lobby\'s own\\n`SharedModules.Packets` (places/Lobby/SharedModules/Packets.luau) returns\\nonly this module. Add a packet here only when Lobby code uses it.","source":{"line":13,"path":"src/ReplicatedStorage/SharedModules/Packets/LobbyShared.luau"}}')}}]);